using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class MarinaNativePropScaleRepair{static MarinaNativePropScaleRepair(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("MarinaNativePropScaleRepair.request"))return;File.Delete("MarinaNativePropScaleRepair.request");var root=PrefabUtility.LoadPrefabContents("Assets/Scenes/Oasis/YachtPortAtlas/Marina Existing City Props Features.prefab");var seen=new HashSet<Mesh>();float shift=204.5909f*.175f;foreach(var t in root.transform.Cast<Transform>()){var f=t.GetComponent<MeshFilter>();if(!f||!f.sharedMesh.name.Contains("Original Prop"))continue;if(seen.Add(f.sharedMesh)){var m=f.sharedMesh;var v=m.vertices;for(int i=0;i<v.Length;i++){v[i].x=(v[i].x+shift)/.65f;v[i].z/=.65f;}m.vertices=v;m.RecalculateBounds();EditorUtility.SetDirty(m);var p=t.localPosition;p.x=p.x*.65f-shift;p.z*=.65f;t.localPosition=p;}}PrefabUtility.SaveAsPrefabAsset(root,"Assets/Scenes/Oasis/YachtPortAtlas/Marina Existing City Props Features.prefab");PrefabUtility.UnloadPrefabContents(root);AssetDatabase.SaveAssets();File.WriteAllText("FinalEnvironmentRoadReview/MarinaNativePropScaleRepair.txt","SUCCESS restored native prop dimensions and compact-layout placements; meshes="+seen.Count);}}
